// tag-append.js
// Create a TAG table, append 100 rows, and print the data (CommonJS)
// Usage: node tag-append.js  (set KEEP=1 to keep the table)

const { createConnection } = require('@machbase/ts-client');

async function main() {
  const host = process.env.MACHBASE_HOST || '127.0.0.1';
  const port = Number(process.env.MACHBASE_PORT || 25656);
  const user = process.env.MACHBASE_USER || 'SYS';
  const password = process.env.MACHBASE_PASSWORD || 'MANAGER';

  console.time('total');
  const conn = createConnection({ host, port, user, password });
  console.time('connect');
  await conn.connect();
  console.timeEnd('connect');

  const reuse = process.env.REUSE === '1';
  const table = reuse && process.env.MB_TABLE
    ? String(process.env.MB_TABLE)
    : 'JS_TAG_' + Math.random().toString(36).slice(2, 7).toUpperCase();
  try {
    // 1) Create TAG table
    if (!reuse) {
      console.time('create');
      await conn.execute(
        `CREATE TAG TABLE "${table}" (name VARCHAR(20) PRIMARY KEY, time DATETIME BASETIME, value DOUBLE SUMMARIZED)`
      );
      console.timeEnd('create');
    } else {
      console.log(`[REUSE] Using existing TAG table: ${table}`);
    }

    // 2) Open append stream (prepared mode by default)
    console.time('appendOpen');
    const stream = await conn.appendOpen(table, [
      { name: 'NAME', type: 'varchar' },
      { name: 'TIME', type: 'int64' },
      { name: 'VALUE', type: 'float64' },
    ]);
    console.timeEnd('appendOpen');

    // 3) Build and append 100 rows
    const base = Date.now();
    const rows = new Array(100);
    for (let i = 0; i < 100; i += 1) {
      const name = `TAG-0`;
      const t = new Date(base + i); // millisecond precision is fine for demo
      const v = Math.random() * 100;
      rows[i] = [name, t, v];
    }
    console.time('append');
    await stream.append(rows);
    console.timeEnd('append');
    console.time('appendClose');
    await stream.close();
    console.timeEnd('appendClose');

    // 4) Query back and print
    console.time('selectCount');
    const [cntRows] = await conn.query(`SELECT COUNT(*) AS CNT FROM "${table}"`);
    console.timeEnd('selectCount');
    console.log('row count:', cntRows[0]?.CNT);

    console.time('selectAll');
    const [allRows] = await conn.query(
      `SELECT NAME, TIME, VALUE FROM "${table}" ORDER BY TIME`
    );
    console.timeEnd('selectAll');
    console.table(allRows);
  } finally {
    if (!reuse && process.env.KEEP !== '1') {
      try { await conn.execute(`DROP TABLE "${table}"`); } catch (_) { /* ignore */ }
    } else {
      console.log(`KEPT table: ${table}`);
    }
    console.time('disconnect');
    await conn.end();
    console.timeEnd('disconnect');
    console.timeEnd('total');
  }
}

main().catch(err => {
  console.error('TAG-APPEND-ERROR', err && err.stack || err);
  process.exit(1);
});
